package com.shiphappens.logistics.controller;
import com.shiphappens.logistics.dto.Requests; import com.shiphappens.logistics.service.IntegrationService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/integrations") public class IntegrationController { private final IntegrationService service; public IntegrationController(IntegrationService service){this.service=service;} @PostMapping("/orders") public ResponseEntity<IntegrationService.Result> submit(@Valid @RequestBody Requests.ExternalOrder request,HttpServletRequest http){var result=service.submit(request,(String)http.getAttribute("requestId"));return ResponseEntity.status(result.idempotent()?HttpStatus.OK:HttpStatus.CREATED).body(result);} }
